/* Grupo Saúde V4 — Enterprise modules: Marketing, Financeiro, Relatórios, Segurança, alertas e governação */
(()=>{'use strict';
const KEY='grupo_saude_v4_demo_2';
const read=()=>{try{return JSON.parse(localStorage.getItem(KEY)||'{}')}catch{return{}}};
const write=s=>localStorage.setItem(KEY,JSON.stringify(s));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const now=()=>new Date().toISOString();
function ensure(){
 const s=read();
 s.clinics=s.clinics||[
  {id:'abrantes',name:'Abranfir — Abrantes',active:true,address:'',email:'',phone:'',gps:null},
  {id:'portimao',name:'AlgarFisio — Portimão',active:true,address:'',email:'',phone:'',gps:null},
  {id:'lagoa',name:'Clínica Particular de Lagoa',active:true,address:'',email:'',phone:'',gps:null},
  {id:'loures',name:'Grupo Saúde — Loures',active:true,address:'',email:'',phone:'',gps:null},
  {id:'medisobral',name:'MediSobral',active:true,address:'',email:'',phone:'',gps:null}
 ];
 s.finance=s.finance||{movements:[],bonusRules:[],acts:[]};
 s.leave=s.leave||[];
 s.alerts=s.alerts||[];
 s.marketing=s.marketing||{campaigns:[],ideas:[],approvals:[],settings:{humanApproval:true,healthAdsCompliance:true,rgpdCheck:true,professionalCredentialCheck:true}};
 s.security=s.security||{backups:[],retentionDays:90,lastRestoreTest:null,health:'orange'};
 s.reports=s.reports||{weeklyInsights:[]};
 write(s);return s;
}
function audit(action,detail,module='Sistema'){const s=ensure();s.audit=s.audit||[];s.audit.unshift({id:'log_'+Date.now(),at:now(),by:s.currentUser||'Sistema',module,action,detail});write(s)}
function modal(title,body){document.getElementById('modalTitle').textContent=title;document.getElementById('modalBody').innerHTML='<div class="modal-body">'+body+'</div>';document.getElementById('modal').showModal()}
function addView(id,title,subtitle){const main=document.querySelector('main');if(!main||document.getElementById(id))return null;const sec=document.createElement('section');sec.id=id;sec.className='view';sec.innerHTML='<div class="page-head"><div><h1>'+title+'</h1><p>'+subtitle+'</p></div></div><div id="'+id+'Content"></div>';main.appendChild(sec);return sec}
function addNav(id,label,icon){const nav=document.getElementById('nav');if(!nav||nav.querySelector('[data-view="'+id+'"]'))return;const b=document.createElement('button');b.dataset.view=id;b.innerHTML=icon+' <span>'+label+'</span>';nav.appendChild(b)}
function show(id){if(window.App?.showView)return window.App.showView(id);if(window.RoleAccessAdminV4&&!RoleAccessAdminV4.guard(id))return;document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===id));document.querySelectorAll('#nav [data-view]').forEach(v=>v.classList.toggle('active',v.dataset.view===id));render(id);document.getElementById('nav')?.classList.remove('open')}
function render(id){({finance:renderFinance,marketing:renderMarketing,reports:renderReports,security:renderSecurity,alerts:renderAlerts,clinics:renderClinics}[id]||(()=>{}))()}
function role(){const s=ensure(),u=(s.users||[]).find?.(x=>x.id===s.currentUser);return u?.role||u?.kind||''}
function allowed(module){const map={finance:'financeManage',marketing:'marketing',reports:'reports',security:'security',alerts:'alerts',hr:'hrManage',audit:'audit',tasks:'clinicTasks',requests:'waiting',operation:'operation'};return window.RoleAccessAdminV4?RoleAccessAdminV4.can(map[module]||module):false}
function finActor(s){return s.employees?.[s.currentUser]||(s.users||[]).find(x=>String(x.id)===String(s.currentUser))||{id:'u1',role:'CEO'}}
function finAdmin(s){const r=String(finActor(s).role||finActor(s).kind||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase();return r==='CEO'||r==='ADMINISTRACAO'}
function finEmployeeId(s,x){if(x.employeeId)return String(x.employeeId);const e=Object.values(s.employees||{}).find(z=>z.name===x.person);return e?String(e.id):''}
function finVisible(s,x){return finAdmin(s)||finEmployeeId(s,x)===String(finActor(s).id||s.currentUser)}
function renderFinance(){
 const s=ensure(),root=document.getElementById('financeContent');if(!root)return;
 if(!allowed('finance')){root.innerHTML='<div class="notice">Sem permissão financeira para este perfil.</div>';return}
 const m=(s.finance.movements||[]).filter(x=>finVisible(s,x)),pending=m.filter(x=>x.status!=='Pago'),paid=m.filter(x=>x.status==='Pago');
 root.innerHTML='<div class="cards"><div class="card"><h3>Movimentos</h3><strong style="font-size:28px">'+m.length+'</strong></div><div class="card"><h3>Por pagar</h3><strong style="font-size:28px">'+pending.length+'</strong></div><div class="card"><h3>Pagos</h3><strong style="font-size:28px">'+paid.length+'</strong></div></div><div class="card" style="margin-top:14px"><div class="row"><h3>Contas correntes</h3>'+(finAdmin(s)?'<button class="primary" onclick="GSEnterprise.newMovement()">+ Movimento</button>':'')+'</div>'+ (m.map(x=>'<div class="row"><div><b>'+esc(x.person)+'</b><div class="meta">'+esc(x.type)+' · '+Number(x.value||0).toFixed(2)+' € · '+esc(x.date)+'</div></div><div><span class="pill '+(x.status==='Pago'?'green':'orange')+'">'+esc(x.status)+'</span> '+(x.status!=='Pago'?'<button class="secondary" onclick="GSEnterprise.pay(\''+x.id+'\')">Marcar pago</button>':'')+'</div></div>').join('')||'<p class="muted">Sem movimentos.</p>')+'</div><div class="notice">Só Administração e CEO podem criar, alterar e aprovar movimentos. Médicos, técnicos e restantes colaboradores consultam apenas a própria conta corrente.</div>';
}
function newMovement(){const s=ensure();if(!finAdmin(s))return alert('Sem permissão para gerir contas de outros colaboradores.');modal('Novo movimento financeiro','<label>Clínica</label><select id="finClinic" onchange="GSEnterprise.financeEmployeeOptions()"><option value="">Selecionar clínica...</option>'+s.clinics.filter(x=>x.active!==false&&x.operational!==false&&x.id!=='administracao').map(x=>'<option value="'+esc(x.id)+'">'+esc(x.name)+'</option>').join('')+'</select><label>Colaborador</label><select id="finPerson" disabled><option value="">Selecione primeiro a clínica</option></select><label>Tipo</label><select id="finType"><option>Consulta</option><option>Tratamento</option><option>Percentagem de ato</option><option>Bónus</option><option>Fatura</option><option>Recibo</option><option>Ajuste</option></select><label>Valor (€)</label><input id="finValue" type="number" step="0.01"><label>Data</label><input id="finDate" type="date" value="'+now().slice(0,10)+'"><label>Documento</label><input id="finFile" type="file"><button class="primary" onclick="GSEnterprise.saveMovement()">Guardar</button>')}
function financeEmployeeOptions(){const s=ensure(),cid=document.getElementById('finClinic')?.value,sel=document.getElementById('finPerson');if(!sel)return;const es=Object.values(s.employees||{}).filter(e=>e.active!==false&&(Array.isArray(e.clinics)&&e.clinics.length?e.clinics:(e.clinic?[e.clinic]:[])).map(String).includes(String(cid)));sel.disabled=!cid;sel.innerHTML=cid?'<option value="">Selecionar colaborador...</option>'+es.map(e=>'<option value="'+esc(e.id)+'">'+esc(e.name||e.fullName||e.email||e.id)+'</option>').join(''):'<option value="">Selecione primeiro a clínica</option>'}function saveMovement(){const s=ensure(),employeeId=document.getElementById('finPerson').value,clinicId=document.getElementById('finClinic').value,employee=s.employees?.[employeeId],person=employee?.name||employeeId,value=+document.getElementById('finValue').value;if(!clinicId||!employeeId||!value)return alert('Selecione clínica, colaborador e valor.');s.finance.movements.unshift({id:'fm_'+Date.now(),clinicId,employeeId,person,type:document.getElementById('finType').value,value,date:document.getElementById('finDate').value,status:'Por pagar',file:document.getElementById('finFile').files?.[0]?.name||null,createdAt:now()});write(s);audit('Movimento criado',person+'; '+value+' €','Financeiro');document.getElementById('modal').close();renderFinance()}
function pay(id){const s=ensure();if(!finAdmin(s))return;const x=s.finance.movements.find(x=>x.id===id);if(!x)return;x.status='Pago';x.paidAt=now();write(s);audit('Movimento pago',x.person+'; '+x.value+' €','Financeiro');renderFinance()}
function renderMarketing(){
 const s=ensure(),root=document.getElementById('marketingContent');if(!root)return;if(!allowed('marketing')){root.innerHTML='<div class="notice">Sem permissão para Marketing.</div>';return}
 const c=s.marketing.campaigns||[];
 root.innerHTML='<div class="cards"><div class="card"><h3>Agente de Marketing</h3><p class="muted">Prepara campanhas e conteúdos; nunca publica sem aprovação humana.</p><span class="pill green">Aprovação humana obrigatória</span></div><div class="card"><h3>Compliance</h3><p class="muted">Publicidade em saúde + RGPD + cédula/entidade profissional + especialidade + dados da clínica.</p><span class="pill green">Verificação obrigatória</span></div></div><div class="card" style="margin-top:14px"><div class="row"><h3>Campanhas e conteúdos</h3><button class="primary" onclick="GSEnterprise.newCampaign()">+ Preparar conteúdo</button></div>'+(c.map(x=>'<div class="row"><div><b>'+esc(x.title)+'</b><div class="meta">'+esc(x.clinic)+' · '+esc(x.channel)+' · '+esc(x.status)+'</div></div><div>'+(x.status==='Pendente de aprovação'?'<button class="primary" onclick="GSEnterprise.approveCampaign(\''+x.id+'\')">Aprovar</button> <button class="secondary" onclick="GSEnterprise.rejectCampaign(\''+x.id+'\')">Recusar</button>':'<span class="pill green">'+esc(x.status)+'</span>')+'</div></div>').join('')||'<p class="muted">Sem campanhas preparadas.</p>')+'</div><div class="notice"><b>Regra:</b> o agente pode pesquisar tendências, propor calendário, texto e ideias criativas, mas qualquer publicação externa exige validação humana e confirmação de compliance.</div>';
}
function newCampaign(){const s=ensure();modal('Preparar conteúdo de marketing','<label>Clínica</label><select id="mkClinic">'+s.clinics.filter(x=>x.active).map(x=>'<option>'+esc(x.name)+'</option>').join('')+'</select><label>Canal</label><select id="mkChannel"><option>Instagram</option><option>Facebook</option><option>Email</option><option>Website</option></select><label>Título / objetivo</label><input id="mkTitle"><label>Conteúdo proposto</label><textarea id="mkBody" rows="6"></textarea><label>Profissional associado (se aplicável)</label><input id="mkProfessional" placeholder="Nome / cédula / entidade"><button class="primary" onclick="GSEnterprise.saveCampaign()">Enviar para aprovação</button>')}
function saveCampaign(){const s=ensure(),title=document.getElementById('mkTitle').value.trim();if(!title)return alert('Indique o título/objetivo.');s.marketing.campaigns.unshift({id:'mk_'+Date.now(),title,clinic:document.getElementById('mkClinic').value,channel:document.getElementById('mkChannel').value,body:document.getElementById('mkBody').value,professional:document.getElementById('mkProfessional').value,status:'Pendente de aprovação',checks:{healthAds:true,rgpd:true,credential:true},createdAt:now()});write(s);audit('Conteúdo preparado',title,'Marketing');document.getElementById('modal').close();renderMarketing()}
function approveCampaign(id){const s=ensure(),x=s.marketing.campaigns.find(x=>x.id===id);if(!x)return;x.status='Aprovado';x.approvedAt=now();x.approvedBy=s.currentUser;write(s);audit('Conteúdo aprovado',x.title,'Marketing');renderMarketing()}
function rejectCampaign(id){const s=ensure(),x=s.marketing.campaigns.find(x=>x.id===id);if(!x)return;x.status='Recusado';x.rejectedAt=now();write(s);audit('Conteúdo recusado',x.title,'Marketing');renderMarketing()}
function metrics(s){const req=s.requests||[],emp=Object.values(s.employees||{}),mov=s.finance.movements||[];return{requests:req.length,marked:req.filter(x=>x.stage==='Marcado').length,employees:emp.length,revenue:mov.filter(x=>x.status==='Pago').reduce((a,x)=>a+(+x.value||0),0)}}
function renderReports(){const s=ensure(),root=document.getElementById('reportsContent');if(!root)return;const m=metrics(s);root.innerHTML='<div class="cards"><div class="card"><h3>Pedidos</h3><strong style="font-size:28px">'+m.requests+'</strong></div><div class="card"><h3>Marcados</h3><strong style="font-size:28px">'+m.marked+'</strong></div><div class="card"><h3>Colaboradores</h3><strong style="font-size:28px">'+m.employees+'</strong></div><div class="card"><h3>Pagamentos registados</h3><strong style="font-size:28px">'+m.revenue.toFixed(2)+' €</strong></div></div><div class="card" style="margin-top:14px"><h3>Relatórios multidimensionais</h3><p>Filtros previstos: clínica, especialidade, profissional, utilizador, hora, dia, semana, mês, ano e comparação com período/ano anterior.</p><button class="primary" onclick="GSEnterprise.weeklyInsight()">Gerar análise semanal IA</button><div id="weeklyInsights">'+(s.reports.weeklyInsights.map(x=>'<div class="notice"><b>'+esc(x.date)+'</b> — '+esc(x.text)+'</div>').join('')||'<p class="muted">Sem análises geradas.</p>')+'</div></div>'}
function weeklyInsight(){const s=ensure(),m=metrics(s),rate=m.requests?Math.round(m.marked/m.requests*100):0;s.reports.weeklyInsights.unshift({date:now().slice(0,10),text:'Pedidos: '+m.requests+'. Marcados: '+m.marked+' ('+rate+'%). Colaboradores ativos registados: '+m.employees+'. Rever anomalias, tempos de espera e especialidades com maior procura antes de qualquer ação.'});write(s);audit('Análise semanal gerada','Tendências e anomalias','Relatórios');renderReports()}
function renderSecurity(){const s=ensure(),root=document.getElementById('securityContent');if(!root)return;const b=s.security.backups||[];root.innerHTML='<div class="cards"><div class="card"><h3>Estado de saúde</h3><strong style="font-size:28px">'+(s.security.health==='green'?'🟢':s.security.health==='red'?'🔴':'🟠')+'</strong></div><div class="card"><h3>Último backup</h3><b>'+(b[0]?.at?new Date(b[0].at).toLocaleString('pt-PT'):'Ainda não registado')+'</b></div><div class="card"><h3>Último teste de restauro</h3><b>'+esc(s.security.lastRestoreTest||'Pendente')+'</b></div></div><div class="card" style="margin-top:14px"><h3>Centro de Segurança e Backups</h3><p>Backups de base de dados e documentos, encriptação, retenção, histórico, alertas, auditoria e testes de restauro.</p><div class="actions"><button class="primary" onclick="GSEnterprise.recordBackup()">Registar teste de backup</button><button class="secondary" onclick="GSEnterprise.restoreTest()">Registar teste de restauro</button></div></div><div class="notice">Esta preview regista o controlo e a auditoria. A cópia externa real depende do backend/armazenamento de produção e não do localStorage do navegador.</div>'}
function recordBackup(){const s=ensure();s.security.backups.unshift({id:'bk_'+Date.now(),at:now(),status:'OK',kind:'BD + documentos'});s.security.health='green';write(s);audit('Backup verificado','BD + documentos','Segurança');renderSecurity()}
function restoreTest(){const s=ensure();s.security.lastRestoreTest=now().slice(0,10);s.security.health='green';write(s);audit('Teste de restauro','Concluído','Segurança');renderSecurity()}
function renderAlerts(){const s=ensure(),root=document.getElementById('alertsContent');if(!root)return;const a=(s.alerts||[]).filter(x=>!x.to||String(x.to)===String(s.currentUser));root.innerHTML='<div class="card"><h3>Centro de alertas</h3><p class="muted">Alertas clicáveis para tarefas, documentos, ponto, pedidos e financeiro. Os alertas críticos devem também gerar email configurável por clínica.</p>'+(a.map(x=>'<div class="row"><div><b>'+esc(x.title)+'</b><div class="meta">'+esc(x.module)+' · '+esc(x.createdAt)+'</div>'+(x.action==='leaveDetail'?window.HRLeaveUIV4.button('Consultar pedido','open',x.recordId):x.action==='performanceDetail'?'<button type="button" class="secondary" data-performance-action="detail" data-record-id="'+esc(x.entityId)+'">Consultar avaliação</button>':'')+'</div><span class="pill '+(x.read?'':'orange')+'">'+(x.read?'Lido':'Pendente')+'</span></div>').join('')||'<p class="muted">Sem alertas.</p>')+'</div>'}
function renderClinics(){const s=ensure(),root=document.getElementById('clinicsContent');if(!root)return;root.innerHTML='<div class="card"><div class="row"><h3>Clínicas — tabela mestre</h3><button class="primary" onclick="GSEnterprise.newClinic()">+ Clínica</button></div>'+s.clinics.map(x=>'<button class="row" style="width:100%;background:none;border:0;border-bottom:1px solid #eee;text-align:left" onclick="GSEnterprise.editClinic(\''+x.id+'\')"><div><b>'+esc(x.name)+'</b><div class="meta">'+esc(x.address||'Morada por preencher')+' · '+esc(x.email||'Email por preencher')+'</div></div><span class="pill '+(x.active?'green':'')+'">'+(x.active?'Ativa':'Inativa')+'</span></button>').join('')+'</div><div class="notice">Esta tabela é a fonte única para RH, Operação, Pedidos, especialidades, profissionais, tarefas e relatórios.</div>'}
function clinicForm(x={}){modal(x.id?'Editar clínica':'Nova clínica','<label>Nome</label><input id="clName" value="'+esc(x.name||'')+'"><label>Morada</label><input id="clAddress" value="'+esc(x.address||'')+'"><label>Email</label><input id="clEmail" value="'+esc(x.email||'')+'"><label>Telefone</label><input id="clPhone" value="'+esc(x.phone||'')+'"><label><input id="clActive" type="checkbox" '+(x.active!==false?'checked':'')+'> Ativa</label><button class="primary" onclick="GSEnterprise.saveClinic(\''+(x.id||'')+'\')">Guardar</button>')}
function newClinic(){clinicForm()} function editClinic(id){clinicForm(ensure().clinics.find(x=>x.id===id)||{})}
function saveClinic(id){const s=ensure(),obj={id:id||'cl_'+Date.now(),name:document.getElementById('clName').value.trim(),address:document.getElementById('clAddress').value.trim(),email:document.getElementById('clEmail').value.trim(),phone:document.getElementById('clPhone').value.trim(),active:document.getElementById('clActive').checked};if(!obj.name)return alert('Indique o nome.');const i=s.clinics.findIndex(x=>x.id===id);if(i>=0)s.clinics[i]={...s.clinics[i],...obj};else s.clinics.push(obj);write(s);audit(id?'Clínica alterada':'Clínica criada',obj.name,'Configuração');document.getElementById('modal').close();renderClinics()}
function install(){
 ensure();
 [['clinics','Clínicas','Tabela mestre e dados de cada unidade','⌂'],['finance','Financeiro','Contas correntes, pagamentos, atos e bónus','€'],['reports','Relatórios','Indicadores, evolução, comparações e IA semanal','▥'],['marketing','Marketing IA','Agente de marketing com aprovação humana e compliance','✦'],['alerts','Alertas','Centro de alertas e escalonamentos','!'],['security','Segurança & Backups','Backups, restauro, auditoria e saúde do sistema','◈']].forEach(([id,t,s,i])=>{addView(id,t,s);addNav(id,t,i)});
}
window.GSEnterprise={show,render,newMovement,financeEmployeeOptions,saveMovement,pay,newCampaign,saveCampaign,approveCampaign,rejectCampaign,weeklyInsight,recordBackup,restoreTest,newClinic,editClinic,saveClinic};
document.addEventListener('DOMContentLoaded',()=>setTimeout(install,300));
})();
/* V4 — conta corrente individual, atos, percentagens e bónus */
(()=>{'use strict';const K='grupo_saude_v4_demo_2',R=()=>{try{return JSON.parse(localStorage.getItem(K)||'{}')}catch{return{}}},W=s=>localStorage.setItem(K,JSON.stringify(s)),N=()=>new Date().toISOString(),E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function S(){const s=R();s.finance=s.finance||{};s.finance.movements=s.finance.movements||[];s.finance.acts=s.finance.acts||[];s.finance.bonusRules=s.finance.bonusRules||[];s.audit=s.audit||[];W(s);return s}
function audit(s,a,d){s.audit.unshift({id:'log_'+Date.now(),at:N(),by:s.currentUser,module:'Financeiro',action:a,detail:d})}
function addAct(){const s=S(),person=prompt('Colaborador / profissional');if(!person)return;const kind=prompt('Tipo de ato: Consulta, Tratamento ou Outro ato','Tratamento')||'Tratamento';const qty=+(prompt('Quantidade','1')||0),unit=+(prompt('Valor unitário (€)','0')||0),pct=+(prompt('Percentagem do técnico sobre o ato (%)','0')||0);if(qty<=0)return;const total=qty*unit,commission=total*pct/100,id='act_'+Date.now();s.finance.acts.unshift({id,person,kind,qty,unit,total,pct,commission,date:N().slice(0,10)});s.finance.movements.unshift({id:'fm_'+Date.now(),person,type:kind,value:commission||total,date:N().slice(0,10),status:'Por pagar',sourceAct:id,createdAt:N()});audit(s,'Ato registado',person+' · '+kind+' · '+qty+' · '+(commission||total)+' €');W(s);GSEnterprise.show('finance')}
function addBonus(){const s=S(),person=prompt('Colaborador');if(!person)return;const value=+(prompt('Valor do bónus (€)','0')||0);if(!value)return;const emp=Object.values(s.employees||{}).find(x=>x.name===person);let eligibility={eligible:true,sickDays:0};if(emp&&window.V4Absence?.eligible)eligibility=V4Absence.eligible(emp.id);if(!eligibility.eligible)return alert('Bónus não lançado: colaborador com '+eligibility.sickDays+' dias de baixa no trimestre.');s.finance.movements.unshift({id:'fm_'+Date.now(),person,type:'Bónus trimestral',value,date:N().slice(0,10),status:'Por pagar',createdAt:N()});audit(s,'Bónus lançado',person+' · '+value+' €');W(s);GSEnterprise.show('finance')}
function statement(person){const s=S(),m=s.finance.movements.filter(x=>x.person===person),total=m.reduce((a,x)=>a+(+x.value||0),0),paid=m.filter(x=>x.status==='Pago').reduce((a,x)=>a+(+x.value||0),0);const title='Conta corrente — '+person;document.getElementById('modalTitle').textContent=title;document.getElementById('modalBody').innerHTML='<div class="modal-body"><div class="cards"><div class="card"><h3>Total</h3><b>'+total.toFixed(2)+' €</b></div><div class="card"><h3>Pago</h3><b>'+paid.toFixed(2)+' €</b></div><div class="card"><h3>Por pagar</h3><b>'+(total-paid).toFixed(2)+' €</b></div></div>'+m.map(x=>'<div class="row"><div><b>'+E(x.type)+'</b><div class="meta">'+E(x.date)+(x.paidAt?' · pago '+E(x.paidAt.slice(0,10)):'')+'</div></div><span>'+Number(x.value||0).toFixed(2)+' € · '+E(x.status)+'</span></div>').join('')+'</div>';document.getElementById('modal').showModal()}
function install(){const root=document.getElementById('financeContent');if(!root||root.querySelector('[data-v4-fin-actions]'))return;const d=document.createElement('div');d.dataset.v4FinActions='1';d.className='card';d.style.marginBottom='14px';d.innerHTML='<div class="actions"><button class="primary" onclick="V4Finance.addAct()">+ Consulta / tratamento / ato</button><button class="secondary" onclick="V4Finance.addBonus()">+ Bónus trimestral</button><button class="secondary" onclick="V4Finance.askStatement()">Consultar conta corrente</button></div>';root.prepend(d)}
function askStatement(){const p=prompt('Nome do colaborador/profissional');if(p)statement(p)}
window.V4Finance={addAct,addBonus,statement,askStatement};new MutationObserver(install).observe(document.documentElement,{childList:true,subtree:true});document.addEventListener('DOMContentLoaded',()=>setTimeout(install,600));})();

