/* V4 — Chat dedicado ao Agente de Marketing IA */
(()=>{'use strict';const K='grupo_saude_v4_demo_2',R=()=>{try{return JSON.parse(localStorage.getItem(K)||'{}')}catch{return{}}},W=s=>localStorage.setItem(K,JSON.stringify(s)),N=()=>new Date().toISOString(),E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function S(){const s=R();s.marketing=s.marketing||{};s.marketing.agentChat=s.marketing.agentChat||[];s.marketing.campaigns=s.marketing.campaigns||[];return s}
function open(){const s=S(),clinics=(s.clinics||[]).filter(x=>!x.legacyDemo&&x.active!==false);document.getElementById('modalTitle').textContent='Chat · Agente de Marketing IA';document.getElementById('modalBody').innerHTML='<div class="modal-body"><div class="notice"><b>Compliance obrigatório:</b> o agente prepara conteúdo, mas a versão final tem de passar pela revisão de publicidade em saúde e aprovação humana.</div><div class="actions"><select id="mkClinic"><option value="">Grupo Saúde / todas</option>'+clinics.map(x=>'<option value="'+x.id+'">'+E(x.name)+'</option>').join('')+'</select><select id="mkChannel"><option>Instagram</option><option>Facebook</option><option>LinkedIn</option><option>Google</option><option>Email</option><option>Website</option></select><select id="mkGoal"><option>Informação em saúde</option><option>Divulgar especialidade</option><option>Divulgar clínica</option><option>Campanha sazonal</option><option>Recrutamento</option></select></div><div id="mkChat" style="max-height:360px;overflow:auto">'+messages(s)+'</div><div class="actions"><textarea id="mkPrompt" style="flex:1" placeholder="Ex.: Cria uma publicação para Instagram sobre fisioterapia na clínica de Lagoa..."></textarea><button class="primary" onclick="V4MarketingChat.send()">Pedir publicação</button></div></div>';document.getElementById('modal').showModal()}
function messages(s){return(s.marketing.agentChat||[]).slice(-30).map(m=>'<div class="card"><b>'+(m.role==='user'?'Tu':'Agente Marketing IA')+'</b><div style="white-space:pre-wrap">'+E(m.text)+'</div><div class="meta">'+E(m.at)+'</div></div>').join('')||'<p class="muted">Ainda sem conversa. Pede uma publicação específica ao agente.</p>'}
function send(){const s=S(),text=document.getElementById('mkPrompt').value.trim();if(!text)return;const clinic=document.getElementById('mkClinic').value,channel=document.getElementById('mkChannel').value,goal=document.getElementById('mkGoal').value;s.marketing.agentChat.push({id:'mku_'+Date.now(),role:'user',text,clinic,channel,goal,at:N()});s.marketing.agentChat.push({id:'mka_'+Date.now(),role:'assistant',text:'Pedido recebido: “'+text+'”. Vou preparar a proposta para '+channel+' com objetivo “'+goal+'”. Antes da versão publicável, é obrigatória a consulta/revisão das regras atuais de publicidade em saúde e a tua aprovação.',clinic,channel,goal,at:N(),needsGeneration:true});W(s);open()}
function saveDraft(text,meta={}){const s=S(),legal=window.V4MarketingCompliance?.scan(text);const c={id:'camp_'+Date.now(),title:meta.title||'Publicação pedida no chat',text,clinic:meta.clinic||'',channel:meta.channel||'Instagram',goal:meta.goal||'',status:legal?.pass?'Aguardar aprovação humana':'Bloqueado por compliance',legalReview:legal,createdAt:N(),source:'Marketing AI Chat'};s.marketing.campaigns.unshift(c);s.marketing.agentChat.push({id:'mka_'+Date.now(),role:'assistant',text:'Rascunho criado e enviado para revisão/compliance: '+c.title,at:N(),campaignId:c.id});W(s);return c}
function install(){const root=document.getElementById('marketingContent');if(!root||root.querySelector('[data-marketing-chat]'))return;const b=document.createElement('button');b.className='primary';b.dataset.marketingChat='1';b.textContent='Abrir Chat com Agente IA';b.onclick=open;root.prepend(b)}
window.V4MarketingChat={open,send,saveDraft};document.addEventListener('DOMContentLoaded',()=>setTimeout(install,800));new MutationObserver(install).observe(document.documentElement,{childList:true,subtree:true});})();

/* V4 — backup/restauro verificável e centro de segurança */
(()=>{'use strict';const K='grupo_saude_v4_demo_2',BK='grupo_saude_v4_backups',R=()=>{try{return JSON.parse(localStorage.getItem(K)||'{}')}catch{return{}}},W=s=>localStorage.setItem(K,JSON.stringify(s)),RB=()=>{try{return JSON.parse(localStorage.getItem(BK)||'[]')}catch{return[]}},WB=b=>localStorage.setItem(BK,JSON.stringify(b)),N=()=>new Date().toISOString();
function hash(v){let h=2166136261;for(let i=0;i<v.length;i++){h^=v.charCodeAt(i);h=Math.imul(h,16777619)}return(h>>>0).toString(16)}
function backup(reason='Automático'){const s=R(),raw=JSON.stringify(s),b=RB(),item={id:'bk_'+Date.now(),at:N(),reason,checksum:hash(raw),bytes:raw.length,data:raw,verified:false};try{item.verified=JSON.stringify(JSON.parse(raw))===raw}catch{}b.unshift(item);WB(b.slice(0,30));s.security=s.security||{};s.security.lastBackup={id:item.id,at:item.at,verified:item.verified,checksum:item.checksum};s.audit=s.audit||[];s.audit.unshift({at:N(),by:s.currentUser,module:'Segurança',action:'Backup '+reason,detail:item.id+' · '+(item.verified?'verificado':'falhou')});W(s);return item}
function test(id){const b=RB(),x=b.find(z=>z.id===id);if(!x)return false;try{x.verified=hash(x.data)===x.checksum&&!!JSON.parse(x.data);x.testedAt=N();WB(b);return x.verified}catch{return false}}
function restore(id){const b=RB(),x=b.find(z=>z.id===id);if(!x||!test(id))return alert('Backup inválido ou não verificável.');if(!confirm('Restaurar este backup? O estado atual será guardado primeiro.'))return;backup('Antes de restauro');localStorage.setItem(K,x.data);location.reload()}
function health(){const b=RB(),last=b[0];if(!last)return{level:'red',text:'🔴 Sem backup'};const age=Date.now()-new Date(last.at).getTime();if(last.verified&&age<86400000)return{level:'green',text:'🟢 Backup saudável'};if(age<604800000)return{level:'orange',text:'🟠 Backup requer atenção'};return{level:'red',text:'🔴 Backup desatualizado'}}
function show(){const b=RB(),h=health();document.getElementById('modalTitle').textContent='Backups e restauro';document.getElementById('modalBody').innerHTML='<div class="modal-body"><div class="notice"><b>'+h.text+'</b><br>Na V4 Preview estes backups são locais ao navegador. Produção deverá usar armazenamento externo cifrado e retenção configurável.</div><button class="primary" onclick="V4Backup.backup(\'Manual\');V4Backup.show()">Criar backup agora</button>'+b.map(x=>'<div class="row"><div><b>'+x.at+'</b><div class="meta">'+x.reason+' · '+x.bytes+' bytes · '+(x.verified?'Verificado':'Por verificar')+'</div></div><button class="secondary" onclick="V4Backup.test(\''+x.id+'\');V4Backup.show()">Testar</button> <button class="secondary" onclick="V4Backup.restore(\''+x.id+'\')">Restaurar</button></div>').join('')+'</div>';document.getElementById('modal').showModal()}
window.V4Backup={backup,test,restore,health,show};document.addEventListener('DOMContentLoaded',()=>{const b=RB();if(!b.length||Date.now()-new Date(b[0].at).getTime()>86400000)backup('Automático diário')});})();

